// Real source integration tests. No DB, SMTP or network calls are permitted.
// node --experimental-vm-modules --test scripts/test-ediel-aperak-caller-contract.cjs
const assert=require('node:assert/strict');
const {test}=require('node:test');
const fs=require('node:fs'),path=require('node:path'),{stripTypeScriptTypes}=require('node:module'),{SourceTextModule,SyntheticModule}=require('node:vm');
const root=path.resolve(__dirname, '..');
async function loadEntry(entry) {
 const cache=new Map();
 function synth(key,exports){if(cache.has(key))return cache.get(key);const m=new SyntheticModule(Object.keys(exports),function(){for(const [k,v] of Object.entries(exports))this.setExport(k,v)});cache.set(key,m);return m;}
 function load(file){if(!file.startsWith(root+path.sep))throw Error('SOURCE_OUTSIDE_REPOSITORY');if(cache.has(file))return cache.get(file);let code=stripTypeScriptTypes(fs.readFileSync(file,'utf8'),{mode:'strip',sourceUrl:file});const m=new SourceTextModule(code,{identifier:file});cache.set(file,m);return m;}
 const linker=(specifier,parent)=>{
  if(specifier==='@/lib/supabase/service')return synth(specifier,{supabaseService:new Proxy({},{get(){throw Error('NO_DB_IN_SOURCE_HARNESS')}})});
  if(specifier==='server-only')return synth(specifier,{});
  if(specifier.startsWith('node:')||['crypto','buffer','path','util'].includes(specifier)){const obj=require(specifier);return synth(specifier,{...obj,default:obj});}
  if(!specifier.startsWith('@/')&&!specifier.startsWith('.'))throw Error('EXTERNAL '+specifier+' from '+parent.identifier);
  const file=specifier.startsWith('@/')?path.join(root,specifier.slice(2)):path.resolve(path.dirname(parent.identifier),specifier);
  for(const s of ['','.ts','/index.ts','.json'])if(fs.existsSync(file+s)&&fs.statSync(file+s).isFile()){if((file+s).endsWith('.json'))return synth(file+s,{default:JSON.parse(fs.readFileSync(file+s,'utf8'))});return load(file+s);}
  throw Error('MISSING '+file);
 };
 const m=load(path.join(root,entry));await m.link(linker);await m.evaluate();return m.namespace;
}

const apis=Promise.all([
  loadEntry('lib/ediel/ack.ts'),
  loadEntry('lib/ediel/rulebook/validator.ts'),
  loadEntry('lib/ediel/core/versionRegistry.ts'),
  loadEntry('lib/ediel/rulebook/versionSelector.ts'),
  loadEntry('lib/ediel/core/versionCatalogue.ts'),
]);
const source={id:'source-profile-fixture',direction:'inbound',message_standard:'edifact',
  message_family:'UTILTS_ERR',message_code:'ERR',environment:'test',test_flag:true,
  sender_ediel_id:'12345',receiver_ediel_id:'54321',application_reference:'23-DDQ-E66-T',
  external_reference:'ORIGINAL',transaction_reference:'SOURCE-TX',
  raw_payload:"UNB+UNOC:3+12345:14+54321:14+260910:1200+I'UNH+M+UTILTS:D:02B:UN:E5SE5A'BGM+ERR+ORIGINAL+9'IDE+24+SOURCE-TX'UNT+4+M'UNZ+1+I'"};
async function draft(family='UTILTS_ERR',outcome='positive'){
  const [ack]=await apis;
  return ack.buildAckDraftForSource({sourceMessage:{...source,message_family:family,message_code:family==='PRODAT'?'Z01':family==='UTILTS'?'E66':'ERR'},ackFamily:'APERAK',outcome,applicationErrors:outcome==='negative'?[{ercCode:'42',fieldCode:'301',text:'INCORRECT DATA',referenceQualifier:'TN',referenceNumber:'SOURCE-TX',lineItemReference:null}]:undefined});
}
const expectedVersion=f=>f==='PRODAT'?'E2SE6A':'E5SE5A';
for(const family of ['PRODAT','UTILTS','UTILTS_ERR']) for(const outcome of ['positive','negative']){
  test(`${family} ${outcome}: actual builder, envelope preflight and validator retain the source profile`,async()=>{
    const [,v]=await apis,d=await draft(family,outcome);
    assert.equal(d.messageVersion,expectedVersion(family));
    assert(d.rawPayload.includes(family==='PRODAT'?'APERAK:D:96A:UN:E2SE6A':'APERAK:D:04A:UN:E5SE5A'));
    const result=v.validateRulebookMessage({family:'APERAK',code:'APERAK',direction:'outbound',mode:'send',rawPayload:d.rawPayload,businessDate:'2026-09-30'});
    assert.equal(result.issues.filter(i=>i.blocking||i.severity==='error').length,0);
  });
}
for(const family of ['PRODAT','UTILTS','UTILTS_ERR']) for(const date of ['2026-09-30','2026-10-01']){
  for(const method of ['resolveOutboundMessageVersionRuntimeFromRegistry','resolveInboundAcceptedVersionsRuntimeFromRegistry','resolveCanonicalOutboundVersion','resolveCanonicalInboundAcceptedVersions']){
    test(`${method}: ${family} metadata reaches canonical selection on ${date} without DB fallback`,async()=>{
      const [,,r]=await apis;
      const value=await r[method]({family:'APERAK',code:'APERAK',date,sourceMessageFamily:family,routeDefaultMessageVersion:'WRONG',fallback:'16B'});
      const actual=typeof value==='string'?value:Array.isArray(value)?value[0].version_code:value.selectedVersion;
      assert.equal(actual,expectedVersion(family));
    });
  }
}
for(const family of ['PRODAT','UTILTS_ERR']){
  test(`raw ${family} profile survives inbound registry resolution without internal source metadata`,async()=>{
    const [,,r]=await apis,d=await draft(family);
    assert.deepEqual(await r.resolveCanonicalInboundAcceptedVersions({family:'APERAK',code:'APERAK',date:'2026-09-30',rawPayload:d.rawPayload}),[{version_code:d.messageVersion}]);
  });
  test(`${family}: metadata and persisted version cannot override a conflicting wire header`,async()=>{
    const [,v]=await apis,d=await draft(family),wrong=family==='PRODAT'?'UTILTS':'PRODAT';
    const result=v.validateRulebookMessage({family:'APERAK',code:'APERAK',direction:'outbound',mode:'send',rawPayload:d.rawPayload,businessDate:'2026-09-30',version:expectedVersion(wrong),parsedPayload:{canonicalSourceMessageFamily:wrong}});
    assert(result.issues.some(i=>i.code==='CANONICAL_POLICY_VALIDATION_FAILED'&&i.description.includes('aperak_source_profile_mismatch')));
  });
  test(`${family}: a misleading runtime version cannot replace the raw profile`,async()=>{
    const [,v]=await apis,d=await draft(family);
    const result=v.validateRulebookMessage({family:'APERAK',code:'APERAK',direction:'outbound',mode:'send',rawPayload:d.rawPayload,businessDate:'2026-09-30',version:family==='PRODAT'?'E5SE5A':'E2SE6A'});
    assert(result.issues.some(i=>i.code==='CANONICAL_POLICY_VALIDATION_FAILED'));
  });
}
test('an unknown operational APERAK profile still fails closed despite legacy fallback/route fields',async()=>{
  const [,,r]=await apis;
  await assert.rejects(r.resolveCanonicalOutboundVersion({family:'APERAK',code:'APERAK',date:'2026-09-30',fallback:'E2SE6A',routeDefaultMessageVersion:'E2SE6A'}),/aperak_source_family_required/);
});
test('read-only unbound catalogue never claims one selected APERAK profile',async()=>{
  const [,,,,r]=await apis;
  const catalogue=await r.resolveMessageVersionCatalogue({family:'APERAK',code:'APERAK',date:'2026-09-30'});
  for(const side of [catalogue.outbound,catalogue.inbound]){
    assert.equal(side.selectedVersion,null);assert.equal(side.currentVersion,null);
    assert.equal(side.requiresSourceProfile,true);
    assert.deepEqual(side.acceptedVersions,[]);
    assert.deepEqual(side.availableSourceProfiles,['PRODAT','UTILTS']);
  }
});
test('read-only invalid raw profile stays diagnostic, never a default P profile',async()=>{
  const [,,,,r]=await apis;
  const catalogue=await r.resolveMessageVersionCatalogue({family:'APERAK',code:'APERAK',date:'2026-09-30',rawPayload:"UNH+M+APERAK:D:96A:UN:E5SE5A'"});
  assert.equal(catalogue.outbound.selectedVersion,null);
  assert(catalogue.outbound.sourceProfileError);
});

const profileApi=loadEntry('lib/ediel/rulebook/aperakSourceProfile.ts');
for(const [name,advice,e,c,end] of [
  ['default','', '+', ':', "'"],
  ['custom','UNA^*,! ~','*','^','~'],
]){
  for(const family of ['PRODAT','UTILTS']){
    test(`${name} ${family}: shared UNH parser retains source profile with exact wire token`,async()=>{
      const p=await profileApi;
      const token=['APERAK','D',family==='PRODAT'?'96A':'04A','UN',expectedVersion(family)].join(c);
      assert.equal(p.resolveAperakSourceFamily({rawPayload:`${advice}UNH${e}M${e}${token}${end}`}),family);
    });
  }
}
for(const [name,raw] of [
  ['unknown association',"UNH+M+APERAK:D:96A:UN:UNKNOWN'"],
  ['mixed directory and association',"UNH+M+APERAK:D:96A:UN:E5SE5A'"],
  ['wrong family token',"UNH+M+PRODAT:D:96A:UN:E2SE6A'"],
  ['released component separator',"UNH+M+APERAK?:D:96A:UN:E2SE6A'"],
  ['punctuation in association',"UNH+M+APERAK:D:96A:UN:E2-SE6A'"],
  ['released association suffix',"UNH+M+APERAK:D:96A:UN:E2SE6A?:EXTRA'"],
  ['missing UNH',"BGM+312+ORIGINAL+9'"],
  ['multiple profiles',"UNH+M+APERAK:D:96A:UN:E2SE6A'UNH+N+APERAK:D:04A:UN:E5SE5A'"],
  ['dangling release',"UNH+M+APERAK:D:96A:UN:E2SE6A?"],
  ['empty supplied wire','   '],
]){
  test(`${name}: neither registry nor display may turn malformed wire into an accepted profile`,async()=>{
    const [,,r,,catalogue]=await apis,p=await profileApi;
    assert.throws(()=>p.resolveAperakSourceFamily({rawPayload:raw,sourceMessageFamily:'PRODAT'}),p.AperakSourceProfileError);
    await assert.rejects(r.resolveCanonicalOutboundVersion({family:'APERAK',code:'APERAK',date:'2026-09-30',rawPayload:raw,sourceMessageFamily:'PRODAT'}),/ediel_aperak_/);
    const ui=await catalogue.resolveMessageVersionCatalogue({family:'APERAK',code:'APERAK',date:'2026-09-30',rawPayload:raw,sourceMessageFamily:'PRODAT'});
    assert.equal(ui.outbound.currentVersion,null);assert.deepEqual(ui.inbound.acceptedVersions,[]);
  });
}
test('unrelated unsupported-family errors are not swallowed by the display adapter',async()=>{
  const [,,,,c]=await apis;
  await assert.rejects(c.resolveMessageVersionCatalogue({family:'UNKNOWN',code:'UNKNOWN',date:'2026-09-30'}),/NO_DB_IN_SOURCE_HARNESS/);
});
for(const [family,code,version] of [['PRODAT','Z01','26A'],['UTILTS','E66','E5SE5A'],['UTILTS_ERR','ERR','E5SE5A'],['CONTRL','CONTRL','EDIEL2']]){
  test(`${family}: unaffected source-owned version selection remains independent of route defaults`,async()=>{
    const [,,r]=await apis;
    assert.equal(await r.resolveCanonicalOutboundVersion({family,code,date:'2026-09-30',fallback:'WRONG',routeDefaultMessageVersion:'WRONG'}),version);
  });
}

const inboundApi=loadEntry('lib/ediel/core/inboundVersionEvidence.ts');
const fileApi=loadEntry('lib/ediel/core/fileVersionValidation.ts');
for(const family of ['PRODAT','UTILTS','UTILTS_ERR']){
  test(`${family}: actual file-version adapter preserves raw profile for inbound and outbound`,async()=>{
    const f=await fileApi,d=await draft(family);
    const parsed={messageFamily:'APERAK',messageCode:'APERAK',messageStandard:'edifact',messageVersion:d.messageVersion,validationReport:{ok:true,warnings:[],errors:[]}};
    for(const direction of ['inbound','outbound']){
      const before=JSON.stringify(parsed);
      const result=await f.withFileVersionValidation({parsed,direction,mode:'tgt',rawPayload:d.rawPayload});
      assert.equal(result.resolvedVersion,d.messageVersion);
      assert.equal(result.validationReport.ok,true);
      assert.equal(JSON.stringify(parsed),before);
      if(direction==='inbound')assert.deepEqual(result.validationReport.acceptedVersions,[d.messageVersion]);
    }
  });
  test(`${family}: actual mailbox version annotation preserves receipt date and leaves original untouched`,async()=>{
    const i=await inboundApi,d=await draft(family);
    const input={...d,direction:'inbound',messageReceivedAt:'2026-09-30T12:00:00+02:00',validationReport:{privateEvidence:'retained'},rawPayload:d.rawPayload};
    const before=JSON.stringify(input),result=await i.withAcceptedInboundVersions(input);
    assert.equal(result.validationReport.inboundVersionAccepted,true);
    assert.deepEqual(result.validationReport.acceptedInboundVersions,[d.messageVersion]);
    assert.equal(result.validationReport.inboundVersionCheckDate,'2026-09-30');
    assert.equal(result.validationReport.privateEvidence,'retained');
    assert.equal(JSON.stringify(input),before);
  });
}
test('unknown APERAK wire remains reviewable, with a negative version finding and no state/ACK upgrade',async()=>{
  const i=await inboundApi;
  const input={messageFamily:'APERAK',messageCode:'APERAK',messageStandard:'edifact',messageVersion:null,rawPayload:"UNH+M+APERAK:D:96A:UN:UNKNOWN'",status:'received',ackOutcome:null,messageReceivedAt:'2026-09-30T12:00:00Z'};
  const result=await i.withAcceptedInboundVersions(input);
  assert.equal(result.rawPayload,input.rawPayload);assert.equal(result.status,'received');assert.equal(result.ackOutcome,null);
  assert.equal(result.validationReport.inboundVersionAccepted,false);
  assert.deepEqual(result.validationReport.acceptedInboundVersions,[]);
  assert.equal(result.validationReport.inboundVersionProfileError,'ediel_aperak_wire_profile_invalid');
});
test('mailbox annotation does not ignore a conflicting bound source-family snapshot',async()=>{
  const i=await inboundApi,d=await draft('UTILTS');
  const result=await i.withAcceptedInboundVersions({...d,direction:'inbound',parsedPayload:{canonicalSourceMessageFamily:'PRODAT'}});
  assert.equal(result.validationReport.inboundVersionAccepted,false);
  assert.match(result.validationReport.inboundVersionProfileError,/aperak_source_profile_mismatch/);
});
test('file adapter blocks a corrupt mixed-directory APERAK before registration',async()=>{
  const f=await fileApi;
  await assert.rejects(f.withFileVersionValidation({parsed:{messageFamily:'APERAK',messageCode:'APERAK',messageStandard:'edifact',messageVersion:'E5SE5A',validationReport:{}},direction:'outbound',mode:'tgt',rawPayload:"UNH+M+APERAK:D:96A:UN:E5SE5A'"}),/ediel_aperak_wire_profile_invalid/);
});

test('a successful recheck clears only the current profile diagnostic, retaining other evidence',async()=>{
  const i=await inboundApi,d=await draft('PRODAT');
  const input={...d,direction:'inbound',messageReceivedAt:'2026-09-30T12:00:00Z',validationReport:{inboundVersionProfileError:'old-error',retainedEvidence:{id:'old-check'}}};
  const result=await i.withAcceptedInboundVersions(input);
  assert.equal(result.validationReport.inboundVersionAccepted,true);
  assert.equal(result.validationReport.inboundVersionProfileError,null);
  assert.deepEqual(result.validationReport.retainedEvidence,{id:'old-check'});
  assert.equal(input.validationReport.inboundVersionProfileError,'old-error');
});
